window.RI2_UNITS = {"5":{"unit":5,"code":"RI2-U05","title":"FINDING WONDERS","startNumber":118,"endNumber":136,"entries":[{"number":118,"term":"fossil","sourceTerm":"fossil (n)","spoken":"fossil","ipa":"fossil /ˈfɑːsəl/","type":"noun","meaning":"hóa thạch","definition":"The preserved remains or trace of an ancient living thing.","note":"","example":"The fossil shows that a large sea animal once lived in this region."},{"number":119,"term":"extraordinary ~ unusual >< ordinary","sourceTerm":"extraordinary ~ unusual >< ordinary","spoken":"extraordinary , unusual , ordinary","ipa":"extraordinary /ˌɛkstrəˈɔːrdəˌnɛri/ · unusual /əˈnjuːˌʒuːəl/ · ordinary /ˈɔːrdəˌnɛri/","type":"adjective · adjective · adjective","meaning":"khác thường, phi thường · bình thường, thông thường","definition":"Extraordinary and unusual describe what is not normal; extraordinary is stronger, while ordinary means normal and not special.","note":"extraordinary mạnh hơn unusual; ordinary mang nghĩa thông thường, không có gì đặc biệt.","example":"An unusual bone led to an extraordinary discovery in an otherwise ordinary field."},{"number":120,"term":"occupation ~ job","sourceTerm":"occupation (n) ~ job","spoken":"occupation , job","ipa":"occupation /ˌɑːkjəˈpeɪʃən/ · job /dʒɑːb/","type":"noun","meaning":"nghề nghiệp","definition":"Regular paid work that a person does.","note":"occupation trang trọng và khái quát hơn job; job thường chỉ một công việc/vị trí cụ thể.","example":"Fossil hunting became her occupation after years of field research."},{"number":121,"term":"credit","sourceTerm":"credit (n)","spoken":"credit","ipa":"credit /ˈkrɛdət/","type":"noun","meaning":"sự ghi nhận, công nhận (vì đã góp công sức)","definition":"Public recognition for helping to achieve or create something.","note":"give someone credit for + danh từ/V-ing; take credit for mang nghĩa nhận công về mình.","example":"The local guide received credit for identifying the important fossil site."},{"number":122,"term":"contribute to · contribution","sourceTerm":"contribute to · contribution","spoken":"contribute to , contribution","ipa":"contribute /kəˈntrɪbjut/ · contribution /ˌkɑːntrəˈbjuːʃən/","type":"verb · noun","meaning":"góp phần vào; đóng góp cho · sự hoặc phần đóng góp","definition":"To help cause a result or give something to a shared effort; a contribution is that help or gift.","note":"contribute to + danh từ/V-ing; make a contribution to + danh từ.","example":"Her careful notes contributed to the study and became an important contribution to science."},{"number":123,"term":"be fascinated by/with something · fascinating","sourceTerm":"be fascinated by/with something · fascinating","spoken":"be fascinated by or with something , fascinating","ipa":"fascinated /ˈfæsəˌneɪtəd/ · something /ˈsʌmθɪŋ/ · fascinating /ˈfæsəˌneɪtɪŋ/","type":"adjective · adjective","meaning":"bị cuốn hút, say mê · hấp dẫn, cuốn hút","definition":"A fascinated person is extremely interested; something fascinating causes that strong interest.","note":"be fascinated by/with + sự vật; fascinated mô tả cảm xúc, fascinating mô tả điều gây hứng thú.","example":"The students were fascinated by the museum's fascinating collection of fossils."},{"number":124,"term":"alter # alternative","sourceTerm":"alter # alternative","spoken":"alter , alternative","ipa":"alter /ˈɔːltɚ/ · alternative /ɔˈltɝːnətɪv/","type":"verb · noun · adjective","meaning":"thay đổi, điều chỉnh · phương án hoặc lựa chọn thay thế","definition":"To alter something is to change it; an alternative is another possible choice or option.","note":"alter là động từ “thay đổi”; alternative không phải danh từ của alter và mang nghĩa “phương án thay thế”.","example":"The new evidence altered the theory, so researchers considered an alternative explanation."},{"number":125,"term":"article","sourceTerm":"article (n)","spoken":"article","ipa":"article /ˈɑːrtəkəl/","type":"noun","meaning":"bài báo, bài viết","definition":"A piece of writing published in a newspaper, magazine, or journal.","note":"","example":"The scientist wrote an article explaining why the discovery was important."},{"number":126,"term":"remain · remains","sourceTerm":"remain · remains","spoken":"remain , remains","ipa":"remain /rɪˈmeɪn/ · remains /rɪˈmeɪnz/","type":"verb · noun","meaning":"vẫn còn, vẫn giữ nguyên · phần còn lại; di tích","definition":"To remain is to continue to be in the same state or place; remains are what is left, especially from the past.","note":"remain là động từ; remains luôn ở dạng số nhiều khi mang nghĩa “di tích/phần còn lại”.","example":"The bones remained underground for centuries, and the remains are now kept in a museum."},{"number":127,"term":"remote","sourceTerm":"remote (a)","spoken":"remote","ipa":"remote /rɪˈmoʊt/","type":"adjective","meaning":"xa xôi, từ xa","definition":"Far away from towns, cities, or other populated places.","note":"remote area/location chỉ nơi xa xôi; remote còn có thể mang nghĩa “từ xa”.","example":"The team travelled for two days to reach the remote desert site."},{"number":128,"term":"access · accessible","sourceTerm":"access · accessible","spoken":"access , accessible","ipa":"access /ˈæˌksɛs/ · accessible /æˈksɛsəbəl/","type":"verb · noun · adjective","meaning":"quyền hoặc cách tiếp cận; truy cập · có thể tiếp cận hoặc truy cập được","definition":"Access is the ability or right to reach or use something; accessible means easy or possible to reach or use.","note":"have/gain access to + danh từ; be accessible to + người.","example":"A new road gives researchers access to a site that was not previously accessible."},{"number":129,"term":"entire","sourceTerm":"entire (a)","spoken":"entire","ipa":"entire /ɪˈntaɪɚ/","type":"adjective","meaning":"toàn bộ, hoàn toàn","definition":"Including every part; whole or complete.","note":"the entire + danh từ số ít; dùng khi xem sự vật là một toàn thể hoàn chỉnh.","example":"The team spent the entire summer examining the fossil bed."},{"number":130,"term":"individual","sourceTerm":"individual (a,n)","spoken":"individual","ipa":"individual /ˌɪndəˈvɪdʒəwəl/","type":"noun · adjective","meaning":"cá nhân; cá thể","definition":"A single person or living thing considered separately from a group.","note":"","example":"Each individual fossil was labelled before the collection was moved."},{"number":131,"term":"eventual · eventually # possibly","sourceTerm":"eventual · eventually # possibly","spoken":"eventual , eventually , possibly","ipa":"eventual /əˈvɛntʃuəl/ · eventually /ɪˈvɛntʃəwəli/ · possibly /ˈpɑːsəbli/","type":"adjective · adverb · adverb","meaning":"xảy ra sau cùng, sau một thời gian · cuối cùng, rốt cuộc · có thể, có lẽ","definition":"Eventual describes what happens at the end, and eventually means in the end; possibly means perhaps, not certainly.","note":"eventual không có nghĩa là “có thể”; eventually # possibly.","example":"The team's eventual discovery will eventually go on display and may possibly change current theories."},{"number":132,"term":"predator >< prey","sourceTerm":"predator >< prey","spoken":"predator , prey","ipa":"predator /ˈprɛdətɚ/ · prey /preɪ/","type":"noun · noun","meaning":"động vật săn mồi · con mồi","definition":"A predator hunts another animal; that hunted animal is its prey.","note":"prey là danh từ không đếm được khi nói chung; prey on + động vật mang nghĩa săn, ăn động vật đó.","example":"Tooth marks helped scientists identify the predator and the prey it had attacked."},{"number":133,"term":"expedition","sourceTerm":"expedition (n)","spoken":"expedition","ipa":"expedition /ˌɛkspəˈdɪʃən/","type":"noun","meaning":"cuộc thám hiểm","definition":"An organized journey made for exploration, research, or a special purpose.","note":"go on/lead an expedition; expedition nhấn mạnh mục đích nghiên cứu hoặc thám hiểm.","example":"The university funded an expedition to search for fossils in the desert."},{"number":134,"term":"region # religion","sourceTerm":"region # religion","spoken":"region , religion","ipa":"region /ˈriːdʒən/ · religion /rɪˈlɪdʒən/","type":"noun · noun","meaning":"khu vực, vùng miền · tôn giáo","definition":"A region is a particular area of a country or the world; religion is a system of beliefs about life and God or gods.","note":"region /ˈriːdʒən/ # religion /rɪˈlɪdʒən/: khác cả nghĩa lẫn trọng âm.","example":"Researchers explored a dry region whose local religion protects several ancient sites."},{"number":135,"term":"adapt · adaptation # adopt","sourceTerm":"adapt · adaptation # adopt","spoken":"adapt , adaptation , adopt","ipa":"adapt /əˈdæpt/ · adaptation /ˌædəˈpteɪʃən/ · adopt /əˈdɑːpt/","type":"verb · verb · noun","meaning":"thích nghi; điều chỉnh · sự thích nghi; bản chuyển thể · nhận nuôi; tiếp nhận, áp dụng","definition":"To adapt is to change for new conditions, and an adaptation is such a change; to adopt is to accept or begin using something.","note":"adapt to + điều kiện; adapt something for + mục đích. Adopt mang nghĩa nhận nuôi/áp dụng, không phải “thích nghi”.","example":"The animal adapted to cold through a physical adaptation, while researchers adopted a new method to study it."},{"number":136,"term":"mention","sourceTerm":"mention (v)","spoken":"mention","ipa":"mention /ˈmɛnʃən/","type":"verb","meaning":"đề cập đến…","definition":"To refer to something briefly without giving much detail.","note":"mention + danh từ; không dùng mention about.","example":"The report mentions the fossil but does not describe it in detail."}],"pronunciationFocus":[{"entryNumber":119,"points":[{"category":"word-stress","note":"extraordinary nhấn chính vào âm tiết chứa /ɔːr/; ordinary nhấn âm đầu"}]},{"entryNumber":122,"points":[{"category":"word-stress","note":"contribute nhấn âm tiết thứ hai; contribution chuyển trọng âm sang âm tiết chứa /bjuː/"}]},{"entryNumber":126,"points":[{"category":"final-sound","note":"remain kết thúc bằng /n/; remains thêm âm /z/ ở cuối"}]},{"entryNumber":128,"points":[{"category":"word-stress","note":"access nhấn âm đầu; accessible nhấn âm tiết thứ hai"},{"category":"final-sound","note":"access kết thúc bằng /s/"}]},{"entryNumber":130,"points":[{"category":"word-stress","note":"individual nhấn vào âm tiết chứa /vɪdʒ/"}]},{"entryNumber":134,"points":[{"category":"common-error","note":"region nhấn âm đầu với /iː/; religion nhấn âm tiết thứ hai với /ɪ/"}]},{"entryNumber":135,"points":[{"category":"common-error","note":"adapt có /æ/, còn adopt có /ɑː/ ở âm tiết được nhấn"},{"category":"final-sound","note":"adapt và adopt đều kết thúc bằng cụm /pt/"}]}]}};
